```javascript
// Constants
const gravity = 9.81; // m/s^2
const pendulumLength = 200; // pixels
const timeStep = 0.02; // seconds
const canvas = document.getElementById('pendulum-canvas');
const ctx = canvas.getContext('2d');
const initialAngleInput = document.getElementById('initial-angle');
const releaseButton = document.getElementById('release-button');
const pendulumAngle = parseFloat(initialAngleInput.value);

// Function to clear the canvas
function clearCanvas() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
}

// Function to draw the pendulum
function drawPendulum(angle) {
  ctx.beginPath();
  ctx.moveTo(canvas.width / 2, canvas.height);
  ctx.lineTo(canvas.width / 2 + pendulumLength * Math.sin(angle), canvas.height - pendulumLength * Math.cos(angle));
  ctx.stroke();
}

// Function to update the pendulum's angle
function updatePendulum() {
  pendulumAngle += (gravity / pendulumLength) * (pendulumLength * Math.sin(pendulumAngle)) * timeStep;
  drawPendulum(pendulumAngle);
}

// Main loop
setInterval(() => {
  clearCanvas();
  if (pendulumAngle > 0 && pendulumAngle < Math.PI) {
    updatePendulum();
  } else {
    pendulumAngle = 0;
  }
}, 16); // 16ms = 60Hz

// Release button event listener
releaseButton.addEventListener('click', () => {
  setInterval(() => {
    clearCanvas();
    updatePendulum();
  }, 16);
});
```

